# Hotfix (John, 27 Nov 2026): admins can gift Lanternholder from any Sigils. Since v140 a gift must be paid from bought
# Sigils (pb - gs) so free Sigils from throwaway accounts cannot be pooled; John's admin Sigils are not bought, so his
# gift was refused with 'bought'. Members of the Cognito "admins" group now skip that check and their gifts do not add
# to gs. Normal players keep the v140 rule. Code-only update of lanternhold-perks. Paste into AWS CloudShell (us-east-1).
# Stops if the live code is not the v140 code it expects. Needs John's go.
set -e
TS=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhgift && cd ~/lhgift
curl -s -o live.zip "$(aws lambda get-function --function-name lanternhold-perks --query Code.Location --output text)"
[ "$(unzip -p live.zip index.js | md5sum | cut -c1-32)" = "064f913c106c588b119c4669ccd813f1" ] || { echo "lanternhold-perks is not the v140 code this script expects. Stopping; nothing changed. Ask Claude."; exit 1; }
cp live.zip ~/lhbak/lanternhold-perks-$TS.zip; echo "backup: ~/lhbak/lanternhold-perks-$TS.zip"
mkdir -p perks && echo  | base64 -d > perks/index.js
[ "$(md5sum perks/index.js | cut -c1-32)" = "f1f4f4436df67aeb3a2804b4b44b7621" ] || { echo "The code did not paste cleanly. Stopping; nothing changed."; exit 1; }
rm -f perks.zip && (cd perks && zip -qj ../perks.zip index.js)
aws lambda update-function-code --function-name lanternhold-perks --zip-file fileb://perks.zip >/dev/null
aws lambda wait function-updated --function-name lanternhold-perks
echo "deployed lanternhold-perks (admin gifts). Undo:"
echo "aws lambda update-function-code --function-name lanternhold-perks --zip-file fileb://$HOME/lhbak/lanternhold-perks-$TS.zip"
